import {renderExitLayer,exitNames,type ExitExperiment} from '../src/mobile/competition/exit-experiments'
import {exitEffectPlans} from '../src/mobile/competition/exit-plans'
import {scheduleNativeGraph} from '../src/mobile/competition/native-graph'
import {exitAudioKey} from '../src/mobile/competition/exit-audio'
import {nativeCandidate} from '../src/mobile/competition/candidates'
import {chooseTransition} from '../src/mobile/competition/score'
const SR=44100,put=async(file:string,body:BodyInit)=>{const r=await fetch('/qa-output/'+file,{method:'POST',body});if(!r.ok)throw Error('Save failed '+file)}
async function decode(ctx:BaseAudioContext,asset:any){const r=await fetch('/qa-data/'+asset.url),bytes=await r.arrayBuffer(),h=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(v=>v.toString(16).padStart(2,'0')).join('');if(h!==asset.sha256)throw Error('Source hash mismatch');return ctx.decodeAudioData(bytes)}
function wav(b:AudioBuffer){const raw=new ArrayBuffer(44+b.length*4),v=new DataView(raw),txt=(i:number,s:string)=>[...s].forEach((c,n)=>v.setUint8(i+n,c.charCodeAt(0)));txt(0,'RIFF');v.setUint32(4,raw.byteLength-8,true);txt(8,'WAVEfmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,2,true);v.setUint32(24,SR,true);v.setUint32(28,SR*4,true);v.setUint16(32,4,true);v.setUint16(34,16,true);txt(36,'data');v.setUint32(40,b.length*4,true);for(let i=0;i<b.length;i++)for(let c=0;c<2;c++)v.setInt16(44+4*i+2*c,Math.round(Math.max(-1,Math.min(1,b.getChannelData(c)[i]))*32767),true);return raw}
function prepare(ctx:BaseAudioContext,p:any,a:AudioBuffer,from:number,bpm:number){const start=Math.round((p.exit-3-from)*SR),input=[a.getChannelData(0).slice(start,start+3*SR),a.getChannelData(1).slice(start,start+3*SR)],r=renderExitLayer(p.family,input,SR,bpm),buffer=ctx.createBuffer(2,r.channels[0].length,SR);let peak=0,tailPeak=0;r.channels.forEach((v,c)=>{buffer.copyToChannel(v,c);for(let i=0;i<v.length;i++){peak=Math.max(peak,Math.abs(v[i]));if(i>=3*SR)tailPeak=Math.max(tailPeak,Math.abs(v[i]))}});return{key:exitAudioKey(p),buffer,peakBound:.76*Math.max(peak,Math.max(p.incoming.head.peak,p.incoming.body.peak)+tailPeak),proof:{algorithm:'phone-exit-v1' as const,sourceAssets:[],sourceStart:p.exit-3,sourceEnd:p.exit,outputSha256:'offline-graph-only',sampleRate:SR,frames:buffer.length,peak,tailPeak,peakBound:0}}}
async function render(p:any,a:AudioBuffer,b:AudioBuffer,handoff:number,from:number,bpm:number,cancel=false){const ctx=new OfflineAudioContext(2,Math.ceil((handoff+b.duration)*SR),SR),ag=ctx.createGain(),bg=ctx.createGain(),as=ctx.createBufferSource(),bs=ctx.createBufferSource(),monitor=ctx.createGain();ag.gain.value=.76;bg.gain.value=0;monitor.gain.value=.85;monitor.connect(ctx.destination);ag.connect(monitor);bg.connect(monitor);as.buffer=a;bs.buffer=b;as.connect(ag);bs.connect(bg);as.start(0);bs.start(handoff)
 const ready=prepare(ctx,p,a,from,bpm);if(ready.peakBound>.98)return{unavailable:'actual outgoing / incoming peak budget',peakBound:ready.peakBound}
 const graph=scheduleNativeGraph(ctx,as,ag.gain,bg.gain,monitor,p,handoff,undefined,ready);if(cancel)void ctx.suspend(.5).then(()=>{graph.cancel();void ctx.resume()})
 const audio=await ctx.startRendering();graph.dispose();let peak=0,nativeError=0
 for(let c=0;c<2;c++){const x=audio.getChannelData(c);for(let i=0;i<x.length;i++){if(!Number.isFinite(x[i]))throw Error('nonfinite output');peak=Math.max(peak,Math.abs(x[i]));if(!cancel&&i>Math.ceil((handoff+.58)*SR)&&i-Math.round(handoff*SR)<b.length)nativeError=Math.max(nativeError,Math.abs(x[i]-.646*b.getChannelData(c)[i-Math.round(handoff*SR)]))}}
 if(peak>=.98||nativeError>.002)throw Error('Peak/native continuation failure '+JSON.stringify({peak,nativeError}));return{audio,peak,nativeError,peakBound:ready.peakBound}
}
async function run(){const status=document.querySelector('#status')!,{tracks,corpus}=await fetch('/qa-data/phone-context.json').then(r=>r.json()),results:any[]=[],checks:any[]=[],decoder=new OfflineAudioContext(2,1,SR)
 for(const pair of corpus.pairs){const a=tracks.find((t:any)=>t.id===pair.a.id),b=tracks.find((t:any)=>t.id===pair.b.id),plans=exitEffectPlans(pair.structural,a,b),methods:any[]=[],ab=plans.length?await decode(decoder,pair.inputs.structural.a):null,bb=plans.length?await decode(decoder,pair.inputs.structural.b):null
  for(const p of plans){status.textContent=pair.id+' / '+p.family;const handoff=p.exit-pair.inputs.structural.a.sourceStart,r=await render(p,ab!,bb!,handoff,pair.inputs.structural.a.sourceStart,a.bpm),{audio,...metrics}=r,file=pair.id+'-phone-'+p.family+'.wav';if(audio)await put(file,wav(audio));methods.push({method:p.family,file:audio?file:null,...metrics})}
  const rows=[pair.structural,...(pair.echo?[pair.echo]:[]),...plans].map(p=>nativeCandidate(a,b,p,pair.position,30)),winner=chooseTransition(rows,false).winner;results.push({id:pair.id,a:pair.a,b:pair.b,cohort:pair.cohort,winner:winner?.method,methods,subjectiveListening:'user liked prior desktop kernels; current graph unscored'})
 }
 // Synthetic A covers the whole render, so cancel can be compared sample by sample.
 const pair=corpus.pairs.find((p:any)=>p.id==='pair-08'),a=tracks.find((t:any)=>t.id===pair.a.id),b=tracks.find((t:any)=>t.id===pair.b.id)
 for(const p of exitEffectPlans(pair.structural,a,b)){const d=new OfflineAudioContext(2,1,SR),tone=(hz:number)=>{const x=d.createBuffer(2,SR*9,SR);for(let c=0;c<2;c++)for(let i=0;i<x.length;i++)x.getChannelData(c)[i]=.1*Math.sin(2*Math.PI*hz*i/SR);return x},aa=tone(220),bb=tone(880),from=p.exit-6,r=await render(p,aa,bb,6,from,a.bpm,true);if(!r.audio)throw Error('Synthetic check unavailable');let error=0;const x=r.audio.getChannelData(0);for(let i=SR;i<SR*8;i++)error=Math.max(error,Math.abs(x[i]-.646*aa.getChannelData(0)[i]));if(error>.00001)throw Error('Cancel did not restore A');checks.push({method:p.family,cancelError:error,peak:r.peak})}
 const receipt={complete:true,scope:'actual phone native graph on real verified excerpts',pairs:results,cancelChecks:checks};await put('phone-effects.json',JSON.stringify(receipt,null,2));status.textContent=JSON.stringify({complete:true,pairs:results.length,renders:results.flatMap(r=>r.methods).filter(m=>m.file).length,cancelChecks:checks.length},null,2)
}
document.querySelector('#run')!.addEventListener('click',()=>void run().catch(e=>document.querySelector('#status')!.textContent=String(e)))
